"""ESPHome Light: OpenBridge adapter (generated by `openbridge partner new`, transport filled in).

Talks to an ESPHome device over its local `web_server` REST API (enable `web_server:` in the device YAML;
no cloud, no account). Only the light platform is covered: on/off, brightness and a toggle. OTA updates,
restarts and configuration are refused by policy.

Every write is typed and allowlisted, read back from the device, and undoable exactly when it is reversible.

Status: emulator only. Record real-hardware runs in docs/DEVICE_EVIDENCE.json before claiming support.
The REST shapes below follow the documented web_server API; parsing stays tolerant (ON/on/true,
brightness 0-255 or 0-100) and anything unrecognized fails closed with EsphomeLightError, never as a
fake success.
"""
import base64
import ipaddress
import json
import urllib.error
import urllib.request

READ = {'power': '', 'brightness': '%', 'firmware': ''}
WRITABLE = {'power': ('on', 'off'), 'brightness': tuple(range(0, 101))}
COMMANDS = {'toggle': None}
POLICY = {('firmware', '*'): 'Firmware is never changed by OpenBridge.',
          ('ota', '*'): 'OTA updates are never triggered by OpenBridge.',
          ('restart', '*'): 'OpenBridge never restarts the device.',
          ('configuration', '*'): 'Device configuration is never changed by OpenBridge.'}

TIMEOUT_S = 5
MAX_BODY = 65536


class EsphomeLightBlocked(PermissionError):
    """Refused before anything was sent."""


class EsphomeLightError(OSError):
    """The device could not be reached or answered something unrecognized."""


def _host_allowed(host):
    """Local network only: private/loopback/link-local IPs, *.local names and bare hostnames."""
    h = (host or '').strip().lower().rstrip('.')
    if not h or '/' in h or '\\' in h or '@' in h or ' ' in h:
        return False
    try:
        ip = ipaddress.ip_address(h)
        return ip.is_private or ip.is_loopback or ip.is_link_local
    except ValueError:
        pass
    if h == 'localhost' or h.endswith('.local') or h == 'esphome':
        return True
    return '.' not in h and h.replace('-', '').replace('_', '').isalnum()


def _parse_power(doc):
    state = doc.get('state')
    if isinstance(state, bool):
        return 'on' if state else 'off'
    s = str(state or '').strip().lower()
    if s in ('on', 'true', '1'):
        return 'on'
    if s in ('off', 'false', '0'):
        return 'off'
    raise EsphomeLightError('unrecognized light state %r' % (state,))


def _parse_brightness(doc):
    for key in ('brightness', 'brightness_pct', 'level'):
        if key in doc and doc[key] is not None:
            try:
                v = float(doc[key])
            except (TypeError, ValueError):
                continue
            if key in ('brightness_pct', 'level') or v <= 100 and doc.get('brightness_scale') == 100:
                return max(0, min(100, int(round(v))))
            if 0 <= v <= 255:                       # ESPHome reports 0-255; OpenBridge shows 0-100
                return max(0, min(100, int(round(v * 100 / 255))))
    raise EsphomeLightError('no brightness in %r' % (sorted(doc),))


class EsphomeLightTransport:
    """HTTP client for the ESPHome web_server API. Three methods: read, write, command."""

    def __init__(self, host, light_id, port=80, username=None, password=None, timeout=TIMEOUT_S):
        if not _host_allowed(host):
            raise EsphomeLightBlocked('refusing non-local ESPHome host %r' % (host,))
        if not light_id or not str(light_id).replace('_', '').replace('-', '').isalnum():
            raise EsphomeLightBlocked('bad light id %r' % (light_id,))
        self.base = 'http://%s:%d' % (host.strip(), int(port))
        self.light_id = str(light_id)
        self.timeout = timeout
        self.auth = None
        if username is not None or password is not None:
            raw = ('%s:%s' % (username or '', password or '')).encode()
            self.auth = 'Basic ' + base64.b64encode(raw).decode('ascii')

    def _request(self, method, path, body=None):
        if not path.startswith('/light/') and path != '/device-info':
            raise EsphomeLightBlocked('refusing unexpected ESPHome path %r' % (path,))
        data = None
        headers = {}
        if body is not None:
            data = json.dumps(body).encode()
            headers['Content-Type'] = 'application/json'
        if self.auth:
            headers['Authorization'] = self.auth
        req = urllib.request.Request(self.base + path, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                raw = resp.read(MAX_BODY + 1)
        except (OSError, ValueError) as e:
            raise EsphomeLightError('%s %s failed: %s' % (method, path, e)) from None
        if len(raw) > MAX_BODY:
            raise EsphomeLightError('%s %s answered too much' % (method, path))
        if resp.status >= 400:
            raise EsphomeLightError('%s %s: HTTP %s' % (method, path, resp.status))
        try:
            return json.loads(raw.decode('utf-8')) if raw.strip() else {}
        except ValueError:
            raise EsphomeLightError('%s %s: not JSON' % (method, path)) from None

    def _light_path(self, *parts):
        for p in parts:
            if p not in ('turn_on', 'turn_off', 'toggle'):
                raise EsphomeLightBlocked('refusing unexpected ESPHome action %r' % (p,))
        return '/light/%s%s' % (self.light_id, ''.join('/' + p for p in parts))

    def read(self):
        doc = self._request('GET', '/light/%s' % self.light_id)
        if not isinstance(doc, dict):
            raise EsphomeLightError('light state is not an object')
        state = {'power': _parse_power(doc), 'brightness': _parse_brightness(doc)}
        try:
            info = self._request('GET', '/device-info')
        except EsphomeLightError:
            info = {}
        if isinstance(info, dict):
            for key in ('esphome_version', 'version', 'firmware'):
                if info.get(key):
                    state['firmware'] = str(info[key])[:32]
                    break
        return state

    def write(self, name, value):
        if name == 'power':
            self._request('POST', self._light_path('turn_on' if value == 'on' else 'turn_off'))
        elif name == 'brightness':
            self._request('POST', self._light_path('turn_on'),
                          {'brightness': max(0, min(255, int(round(value * 255 / 100))))})
        else:
            raise EsphomeLightBlocked('%s is not writable on an ESPHome light' % (name,))

    def command(self, name, value=None):
        if name != 'toggle' or value is not None:
            raise EsphomeLightBlocked('%s is not an ESPHome light command' % (name,))
        self._request('POST', self._light_path('toggle'))


def _refusal(name, value):
    return POLICY.get((name, value)) or POLICY.get((name, '*'))


class EsphomeLight:
    def __init__(self, transport):
        self.transport = transport
        self._before = {}

    def facts(self):
        state = self.transport.read()
        return [{'name': k, 'value': state[k], 'unit': unit} for k, unit in READ.items() if k in state]

    def set_reversible(self, name, value):
        reason = _refusal(name, value)
        if reason:
            raise EsphomeLightBlocked(reason)
        if name not in WRITABLE or value not in WRITABLE[name]:
            raise EsphomeLightBlocked('%s=%r is not an allowed setting' % (name, value))
        if name in self._before:
            raise EsphomeLightBlocked('this setting has a pending Undo; undo it before changing it again')
        before = self.transport.read()
        if name not in before:
            raise EsphomeLightBlocked('the device does not report %s' % name)
        self.transport.write(name, value)
        after = self.transport.read().get(name)
        verified = after == value
        if verified:
            self._before[name] = before[name]
        return {'setting': name, 'before': before[name], 'after': after, 'verified': verified, 'reversible': True}

    def undo(self, name):
        if name not in self._before:
            raise EsphomeLightBlocked('nothing to undo for %s' % name)
        target = self._before[name]
        self.transport.write(name, target)
        now = self.transport.read().get(name)
        if now == target:
            self._before.pop(name)
        return {'setting': name, 'restored': now, 'exact': now == target}

    def command(self, name, value=None):
        reason = _refusal(name, value)
        if reason:
            raise EsphomeLightBlocked(reason)
        if name not in COMMANDS or (COMMANDS[name] is None and value is not None) or (COMMANDS[name] is not None and value not in COMMANDS[name]):
            raise EsphomeLightBlocked('%s is not an allowed command' % name)
        self.transport.command(name, value)
        # Momentary commands leave no lasting state to read back: reported as executed, never as verified.
        return {'command': name, 'value': value, 'verified': None, 'reversible': False}
